def num_islands(grid):
    if not grid:
        return 0
    rows, cols = len(grid), len(grid[0])
    g = [row[:] for row in grid]

    def flood(r, c):
        if r < 0 or r >= rows or c < 0 or c >= cols or g[r][c] != '1':
            return
        g[r][c] = '0'
        flood(r + 1, c)
        flood(r - 1, c)
        flood(r, c + 1)
        flood(r, c - 1)

    count = 0
    for r in range(rows):
        for c in range(cols):
            if g[r][c] == '1':
                count += 1
                flood(r, c)
    return count

